<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Database,Request,Response,Session,View};use App\Models\Repositories\{AdminRepository,BillingRepository,CampaignRepository,ContactRepository,UserRepository};use App\Services\{AccountLifecycle,ContactImporter,CpfCnpjValidator,Crypto,PagSeguroClient,PaymentWebhook,PlatformMailer,RateLimiter,UploadGuard};
final class AppController {private UserRepository $users;private ContactRepository $contacts;private CampaignRepository $campaigns;private AdminRepository $admin;private BillingRepository $billing;private AccountLifecycle $lifecycle;private \PDO $db;private array $config;
 public function __construct(){ $this->config=require dirname(__DIR__,2).'/config.php';$db=Database::connect($this->config);$this->db=$db;$this->users=new UserRepository($db);$this->contacts=new ContactRepository($db);$this->campaigns=new CampaignRepository($db);$this->admin=new AdminRepository($db);$this->billing=new BillingRepository($db);$this->lifecycle=new AccountLifecycle($db);}
 private function csrf(Request $r):void{if(!Session::verifyCsrf($r->input('_csrf')))throw new \RuntimeException('Sessão expirada; recarregue a página.');} private function user():int{if(!($id=Session::userId()))Response::redirect('/login');return$id;}private function paidUser():int{$id=$this->user();if(!$this->users->canUseApp($id))Response::redirect('/planos');return$id;} private function render(string $view,array $d=[]):never{View::render($view,$d+['csrf'=>Session::csrf(),'flash'=>Session::flash('message'),'userId'=>Session::userId()]);}
 public function home():never{$this->render('landing');} public function loginForm():never{$this->render('login');} public function registerForm():never{$this->render('register');}
 public function terms():never{$this->render('terms');}public function privacy():never{$this->render('privacy');}
 public function register(Request $r):never{$this->csrf($r);$name=trim((string)$r->input('name'));$email=strtolower(trim((string)$r->input('email')));if(!(new RateLimiter($this->db))->allow('register',$email,3,60)){Session::flash('message','Muitas tentativas.');Response::redirect('/cadastro');}$pass=(string)$r->input('password');$type=(string)$r->input('person_type');$doc=(string)$r->input('document');if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8||$pass!==$r->input('password_confirmation')||!(new CpfCnpjValidator())->valid($doc,$type)){Session::flash('message','Revise os dados: senha mínima de 8 caracteres e CPF/CNPJ válido.');Response::redirect('/cadastro');}$crypto=new Crypto($this->config['app']['encryption_key']);try{$id=$this->users->create(['name'=>$name,'email'=>$email,'password'=>password_hash($pass,PASSWORD_BCRYPT),'phone'=>trim((string)$r->input('phone')),'type'=>$type,'cipher'=>$crypto->encrypt(preg_replace('/\D/','',$doc)),'hash'=>hash('sha256',preg_replace('/\D/','',$doc))]);$token=$this->users->createToken($id,'email_verification');try{(new PlatformMailer($this->config))->send($email,'Confirme seu cadastro','<p><a href="'.$this->config['app']['url'].'/ativar?token='.$token.'">Confirmar e-mail</a></p>');}catch(\Throwable){}Session::flash('message','Cadastro criado. Verifique seu e-mail para ativar a conta.');}catch(\Throwable){Session::flash('message','E-mail ou documento já cadastrado.');}Response::redirect('/login');}
 public function login(Request $r):never{$this->csrf($r);$email=strtolower(trim((string)$r->input('email')));if(!(new RateLimiter($this->db))->allow('login',$email)){Session::flash('message','Muitas tentativas. Tente mais tarde.');Response::redirect('/login');}$u=$this->users->findByEmail($email);if(!$u||!password_verify((string)$r->input('password'),$u['password_hash'])){Session::flash('message','Credenciais inválidas.');Response::redirect('/login');}if(!$u['email_verified_at']){Session::flash('message','Confirme seu e-mail antes de entrar.');Response::redirect('/login');}Session::login((int)$u['id']);Response::redirect('/painel');}
 public function logout():never{Session::logout();Response::redirect('/');} public function dashboard():never{$id=$this->user();$this->render('dashboard',['stats'=>$this->contacts->stats($id),'campaigns'=>$this->campaigns->list($id),'subscribed'=>$this->users->activeSubscription($id)]);}
 public function contacts():never{$id=$this->paidUser();$this->render('contacts',['data'=>$this->contacts->list($id,(string)($_GET['q']??''),(int)($_GET['p']??1))]);}
 public function import(Request $r):never{$id=$this->user();$this->csrf($r);$content=(string)$r->input('emails');$source='manual';if(($f=$r->files('file'))&&$f['error']===UPLOAD_ERR_OK){[$path]=(new UploadGuard())->storeList($f,dirname(__DIR__,2).'/storage/uploads/lists');$content=(new ContactImporter())->readFile($path,pathinfo($f['name'],PATHINFO_EXTENSION));$source='file';}$res=(new ContactImporter())->extract($content);[$add,$sup]=$this->contacts->addMany($id,$res['emails'],$source);Session::flash('message',"Importação: {$add} adicionados, {$res['duplicates']} duplicados, {$sup} bloqueados.");Response::redirect('/contatos');}
 public function exportContacts():never{$id=$this->user();header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="contatos.csv"');$out=fopen('php://output','w');fputcsv($out,['email','nome','status','origem','cadastrado_em']);foreach($this->contacts->export($id) as $row)fputcsv($out,$row);fclose($out);exit;}
 public function plans():never{$this->user();$this->render('plans',['plans'=>$this->billing->plans()]);}
 public function notifications():never{$id=$this->user();$this->render('notifications',['notifications'=>$this->users->notifications($id)]);}
 public function checkout(Request $r):never{$u=$this->user();$this->csrf($r);$plan=$this->billing->plan((string)$r->input('plan'));$method=(string)$r->input('method');if(!$plan||!in_array($method,['credit_card','pix','boleto'],true))throw new \RuntimeException('Plano ou meio inválido.');if($plan['is_recurring']&&$method!=='credit_card'){$plan['is_recurring']=false;}$ref='MLG-'.$u.'-'.bin2hex(random_bytes(8));$this->billing->createPending($u,$plan,$method,$ref);$payload=['reference_id'=>$ref,'items'=>[['name'=>$plan['name'],'quantity'=>1,'unit_amount'=>$plan['amount_cents']]],'notification_urls'=>[rtrim($this->config['app']['url'],'/').'/webhooks/pagamentos'],'redirect_url'=>rtrim($this->config['app']['url'],'/').'/painel'];if($plan['is_recurring']&&$method==='credit_card')$payload['recurrence_plan']=['name'=>$plan['name'],'interval'=>'MONTHLY','billing_cycles'=>0];try{$response=(new PagSeguroClient($this->config['billing']))->createCheckout($payload);$url=$response['links'][0]['href']??$response['payment_url']??null;if(!$url)throw new \RuntimeException('Checkout sem URL.');$this->billing->checkoutUrl($ref,$url);Response::redirect($url);}catch(\Throwable $e){Session::flash('message','Não foi possível iniciar o checkout: '.$e->getMessage());Response::redirect('/planos');}}
 public function deleteContact(Request $r):never{$id=$this->user();$this->csrf($r);$this->contacts->delete((int)$r->input('id'),$id);Response::redirect('/contatos');}public function deleteContacts(Request $r):never{$id=$this->user();$this->csrf($r);$ids=(array)$r->input('ids',[]);if($r->input('id'))$ids[]=(int)$r->input('id');$this->contacts->deleteMany($ids,$id);Response::redirect('/contatos');}
 public function campaignForm():never{$this->user();$this->render('campaign');} public function campaignCreate(Request $r):never{$id=$this->user();$this->csrf($r);$c=$this->campaigns->create($id,['title'=>trim((string)$r->input('title')),'subject'=>trim((string)$r->input('subject')),'body'=>(string)$r->input('body'),'links'=>['site'=>$r->input('site'),'instagram'=>$r->input('instagram'),'linkedin'=>$r->input('linkedin'),'facebook'=>$r->input('facebook')]]);if(($f=$r->files('image'))&&$f['error']===UPLOAD_ERR_OK){[$path,$mime]=(new UploadGuard())->storeImage($f,dirname(__DIR__,2).'/storage/uploads/campaigns');$this->campaigns->addImage($c,$path,$mime,(int)$f['size'],trim((string)$r->input('image_description')));}$this->audit($id,'campaign_created',['campaign_id'=>$c]);Session::flash('message',"Rascunho #{$c} salvo.");Response::redirect('/painel');}
 public function campaignFinalize(Request $r):never{$u=$this->user();$this->csrf($r);$this->campaigns->finalize((int)$r->input('id'),$u,$this->campaigns->hourlyLimit($u));Session::flash('message','Campanha enfileirada.');Response::redirect('/painel');}
 public function campaignStatus(Request $r):never{$u=$this->user();$this->campaigns->setStatus((int)$r->input('id'),$u,(string)$r->input('status'));Response::redirect('/painel');}
 public function campaignDashboard(Request $r):never{$u=$this->user();$d=$this->campaigns->dashboard((int)$r->input('id'),$u);$d['eta_minutes']=ceil(((int)($d['pending']??0)/5)*10);Response::json($d);}
 public function optoutForm(Request $r):never{$token=(string)$r->input('token');$c=$this->contacts->byToken($token);$this->render('optout',['token'=>$token,'email'=>$c?preg_replace('/(?<=^.{2}).(?=[^@]*@)/','*',$c['email']):'']);}public function optout(Request $r):never{$this->csrf($r);$out=$this->contacts->optOut((string)$r->input('token'),trim((string)$r->input('reason'))?:null);$this->render('optout_done',['status'=>$out]);}
 private function superAdmin():void{if(!$this->admin->isAdmin($this->user()))Response::html('<h1>403</h1>',403);}
 public function enforceAccess(Request $r):void{$public=['/','/login','/cadastro','/esqueci-senha','/redefinir','/ativar','/descadastro','/termos','/privacidade','/health','/webhooks/pagamentos'];if(in_array($r->path(),$public,true))return;if(!Session::userId())Response::redirect('/login');if(in_array($r->path(),['/planos','/checkout','/configuracoes','/configuracoes/smtp','/configuracoes/smtp-teste','/configuracoes/cancelar'],true))return;if(!$this->users->canUseApp((int)Session::userId()))Response::redirect('/planos');}
 public function admin():never{$this->superAdmin();$this->render('admin',['data'=>$this->admin->overview()]);}
 public function adminBlock(Request $r):never{$this->superAdmin();$this->csrf($r);$this->admin->block((int)$r->input('user_id'),trim((string)$r->input('reason'))?:'Inadimplência');Response::redirect('/admin');}
 public function adminUnblock(Request $r):never{$this->superAdmin();$this->csrf($r);$this->admin->unblock((int)$r->input('user_id'));Response::redirect('/admin');}
 public function webhook():never{$body=(string)file_get_contents('php://input');if(!PaymentWebhook::verify($body,$_SERVER['HTTP_X_WEBHOOK_SIGNATURE']??null,$this->config['billing']['webhook_secret']??''))Response::json(['ok'=>false]);$p=json_decode($body,true,512,JSON_THROW_ON_ERROR);$this->admin->processPayment((string)($p['provider']??'pagseguro'),(string)($p['id']??hash('sha256',$body)),$p);Response::json(['ok'=>true]);}
 public function settings():never{$this->user();$this->render('settings');} public function cancel(Request $r):never{$id=$this->user();$this->csrf($r);$this->lifecycle->requestCancel($id);Session::flash('message','Cancelamento solicitado. Nenhuma nova cobrança será emitida.');Response::redirect('/configuracoes');}
 public function senderSave(Request $r):never{$user=$this->user();$this->csrf($r);$limit=(int)$r->input('hourly_limit');if($limit<1||$limit>200||!filter_var($r->input('from_email'),FILTER_VALIDATE_EMAIL))throw new \RuntimeException('Configuração de remetente inválida.');$pass=(string)$r->input('smtp_password');$cipher=$pass?(new Crypto($this->config['app']['encryption_key']))->encrypt($pass):null;$sql='INSERT INTO sender_settings(user_id,display_name,from_email,reply_to_email,smtp_host,smtp_port,smtp_username,smtp_password_ciphertext,smtp_security,hourly_limit) VALUES(:u,:n,:f,:r,:h,:p,:login,:pass,:sec,:lim) ON DUPLICATE KEY UPDATE display_name=VALUES(display_name),from_email=VALUES(from_email),reply_to_email=VALUES(reply_to_email),smtp_host=VALUES(smtp_host),smtp_port=VALUES(smtp_port),smtp_username=VALUES(smtp_username),smtp_security=VALUES(smtp_security),hourly_limit=VALUES(hourly_limit),smtp_password_ciphertext=IF(:haspass,VALUES(smtp_password_ciphertext),smtp_password_ciphertext)';$s=$this->db->prepare($sql);$s->execute(['u'=>$user,'n'=>trim((string)$r->input('display_name')),'f'=>$r->input('from_email'),'r'=>$r->input('reply_to_email')?:null,'h'=>$r->input('smtp_host'),'p'=>(int)$r->input('smtp_port'),'login'=>$r->input('smtp_username'),'pass'=>$cipher??'','sec'=>$r->input('smtp_security'),'lim'=>$limit,'haspass'=>$pass!==''?1:0]);$this->audit($user,'smtp_updated');Session::flash('message','SMTP salvo. A senha não será exibida novamente.');Response::redirect('/configuracoes');}
 public function smtpTest(Request $r):never{$u=$this->user();$this->csrf($r);$q=$this->db->prepare('SELECT * FROM sender_settings WHERE user_id=:u');$q->execute(['u'=>$u]);$s=$q->fetch();try{if(!$s)throw new \RuntimeException('SMTP não configurado.');$s['password']=(new Crypto($this->config['app']['encryption_key']))->decrypt($s['smtp_password_ciphertext']);(new \App\Services\SmtpMailer())->send($s,$s['from_email'],'Teste Mailing','<p>Configuração SMTP válida.</p>','Configuração SMTP válida.',$s['from_email'],$s['reply_to_email']??'');$this->audit($u,'smtp_test');Session::flash('message','Teste SMTP enviado.');}catch(\Throwable $e){Session::flash('message','Falha SMTP: '.$e->getMessage());}Response::redirect('/configuracoes');}
 public function forgotForm():never{$this->render('forgot');} public function forgot(Request $r):never{$this->csrf($r);$email=strtolower(trim((string)$r->input('email')));if(!(new RateLimiter($this->db))->allow('forgot',$email,3,60))Response::html('<h1>Muitas tentativas</h1>',429);$u=$this->users->findByEmail($email);if($u){$token=$this->users->createToken((int)$u['id'],'password_reset');try{(new PlatformMailer($this->config))->send($email,'Redefinição de senha','<p><a href="'.$this->config['app']['url'].'/redefinir?token='.$token.'">Redefinir senha</a></p>');}catch(\Throwable){}}Session::flash('message','Se o e-mail existir, você receberá instruções.');Response::redirect('/login');}
 public function activate(Request $r):never{$t=$this->users->useToken((string)$r->input('token'),'email_verification');if($t)$this->users->verify((int)$t['user_id']);Session::flash('message',$t?'E-mail confirmado. Agora você pode entrar.':'Link inválido ou expirado.');Response::redirect('/login');}
 public function resetForm(Request $r):never{$this->render('reset',['token'=>(string)$r->input('token')]);} public function reset(Request $r):never{$this->csrf($r);$pass=(string)$r->input('password');$t=$this->users->useToken((string)$r->input('token'),'password_reset');if(!$t||strlen($pass)<8){Session::flash('message','Link inválido ou senha curta.');Response::redirect('/login');}$this->users->resetPassword((int)$t['user_id'],password_hash($pass,PASSWORD_BCRYPT));Session::flash('message','Senha atualizada.');Response::redirect('/login');}
 private function audit(int $user,string $event,array $metadata=[]):void{$s=$this->db->prepare('INSERT INTO audit_logs(user_id,event_type,ip_address,metadata) VALUES(:u,:e,INET6_ATON(:ip),:m)');$s->execute(['u'=>$user,'e'=>$event,'ip'=>$_SERVER['REMOTE_ADDR']??'127.0.0.1','m'=>json_encode($metadata)]);}
}
